// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Charge_Intent_Qualification_Api {
  def id: Art.BridgeId
  def intent_sample_Id : Art.PortId
  def qualified_intent_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_intent: Drone_Battery_Charge_Supervisor.QualifiedChargeIntent.Type = $

  def put_qualified_intent(value : Drone_Battery_Charge_Supervisor.QualifiedChargeIntent.Type) : Unit = {
    Contract(
      Modifies(qualified_intent),
      Ensures(
        qualified_intent == value
      )
    )
    Spec {
      qualified_intent = value
    }

    Art.putValue(qualified_intent_Id, Drone_Battery_Charge_Supervisor.QualifiedChargeIntent_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Charge_Intent_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val intent_sample_Id : Art.PortId,
  val qualified_intent_Id : Art.PortId) extends Charge_Intent_Qualification_Api

@datatype class Charge_Intent_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val intent_sample_Id : Art.PortId,
  val qualified_intent_Id : Art.PortId) extends Charge_Intent_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var intent_sample: Drone_Battery_Charge_Supervisor.ChargeIntentSample = $

  def get_intent_sample() : Option[Drone_Battery_Charge_Supervisor.ChargeIntentSample] = {
    Contract(
      Ensures(
        Res == Some(intent_sample)
      )
    )
    val value : Option[Drone_Battery_Charge_Supervisor.ChargeIntentSample] = Art.getValue(intent_sample_Id) match {
      case Some(Drone_Battery_Charge_Supervisor.ChargeIntentSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port intent_sample.  Expecting 'Drone_Battery_Charge_Supervisor.ChargeIntentSample_Payload' but received ${v}")
        None[Drone_Battery_Charge_Supervisor.ChargeIntentSample]()
      case _ => None[Drone_Battery_Charge_Supervisor.ChargeIntentSample]()
    }
    return value
  }
}
